cedar_policies.cedar_text:
@id("allow-policy-set-read")
permit (
    principal is MIP::User,
    action == MIP::Action::"policy_sets:read",
    resource is MIP::PolicySet
);

@id("deny-deployment-key-policy-set-delete")
forbid (
    principal is MIP::ApiKey,
    action == MIP::Action::"policy_sets:delete",
    resource is MIP::PolicySet
)
when {
    principal.scope_type == "DEPLOYMENT"
};
